[b,a] = besself(4,1000);
fprintf('%.4g ', a); fprintf('\n');
[h,w] = freqs(b,a,[100 1000 5000]);
fprintf('%.4f\n', abs(h))

[bz,az] = bilinear(1,[1 1],1);
fprintf('%.4f ', bz, az); fprintf('\n');
[bz,az] = bilinear(1,[1 1],1,0.1);
fprintf('%.4f ', bz, az); fprintf('\n');

[z,p,k] = buttap(2);
[b,a] = zp2tf(z,p,k);
fs = 1000; wc = 2*fs*tan(pi*100/fs);
[bs,as] = lp2lp(b,a,wc);
[bz,az] = bilinear(bs,as,fs);
fprintf('%.4f ', bz); fprintf('\n');
fprintf('%.4f ', az); fprintf('\n');

b = 1; a = [1 sqrt(2) 1];
[h,w] = freqs(b,a,5);
disp(size(h))
fprintf('%.4g\n', w([1 end]))

[bz,az] = impinvar(1,[1 3 2],10);
fprintf('%.5f ', bz); fprintf('\n');
fprintf('%.5f ', az); fprintf('\n');

[b,a] = butter(2,1,'s');
[bt,at] = lp2bp(b,a,100,20);
w = [90 100 110];
h = polyval(bt,1j*w)./polyval(at,1j*w);
fprintf('%.4f\n', abs(h));
